{
  "name": "化学气相沉积（CVD）设备控制系统",
  "name_en": "Chemical Vapor Deposition (CVD) System Controller",
  "manufacturer": "",
  "description": "用于化学气相沉积实验装置的工艺控制界面，通常围绕温度与多路气体流量配方进行设置、运行和监控。可在实验中管理配方文件、下发设定值并观察过程趋势曲线，支持薄膜生长等CVD工艺流程。",
  "description_en": "A process control interface for a chemical vapor deposition (CVD) setup, typically handling temperature and multi-gas flow recipes for run control and monitoring. It is used in lab workflows to manage recipe files, apply setpoints, and view process trend plots during CVD thin-film growth experiments.",
  "actions": [
    {
      "action_name": "auto-return_ui_fields",
      "description": "返回当前界面中的工艺参数字段值。",
      "description_en": "Return the current process-parameter field values from the UI."
    },
    {
      "action_name": "auto-save_recipe",
      "description": "保存当前CVD工艺配方到文件（含元数据与参数表）。",
      "description_en": "Save the current CVD process recipe to a file (including metadata and parameter table)."
    },
    {
      "action_name": "auto-open_recipe",
      "description": "从文件打开并加载CVD工艺配方到控制界面。",
      "description_en": "Open a CVD process recipe file and load it into the control interface."
    },
    {
      "action_name": "auto-update_plot",
      "description": "更新工艺趋势图（如各路气体流量随时间变化）。",
      "description_en": "Update the process trend plots (such as time-varying gas flow channels)."
    },
    {
      "action_name": "auto-start_recipe",
      "description": "启动配方运行并开始过程监控。",
      "description_en": "Start recipe execution and begin process monitoring."
    },
    {
      "action_name": "auto-stop_recipe",
      "description": "停止当前配方运行。",
      "description_en": "Stop the current recipe run."
    },
    {
      "action_name": "auto-apply_setpoints",
      "description": "应用温度/流量等工艺设定值到系统。",
      "description_en": "Apply process setpoints (e.g., temperature/flow) to the system."
    }
  ],
  "tag_hints": [
    "CVD process control",
    "recipe management",
    "gas flow setpoints",
    "temperature setpoint",
    "thin film deposition",
    "process trend plotting"
  ]
}
